// Check that the font files in the repository match the outputs in scripts/fonts/fonts.lock.json, that every font comes with OFL.txt,
// and that every file referenced by fonts.css exists. The fonts are generated by scripts/fonts/build_fonts.py; this check does not need Python.
import { createHash } from 'node:crypto'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const webDir = fileURLToPath(new URL('../', import.meta.url))
const lock = JSON.parse(readFileSync(join(webDir, 'scripts/fonts/fonts.lock.json'), 'utf8'))
const outputs = lock.outputs ?? {}
const problems = []

const sha256 = (path) => createHash('sha256').update(readFileSync(path)).digest('hex')

function filesUnder(dir) {
  if (!existsSync(dir)) return []
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name)
    return statSync(path).isDirectory() ? filesUnder(path) : [path]
  })
}

if (Object.keys(outputs).length === 0) problems.push('the lock file has no outputs; run build_fonts.py first')

for (const [path, expected] of Object.entries(outputs)) {
  const full = join(webDir, path)
  if (!existsSync(full)) problems.push(`${path} is missing`)
  else if (sha256(full) !== expected) problems.push(`${path} does not match the lock file`)
}

const tracked = [...filesUnder(join(webDir, 'src/assets/fonts')), ...filesUnder(join(webDir, 'public/fonts'))]
for (const full of tracked) {
  const path = relative(webDir, full).split('\\').join('/')
  if (!(path in outputs) && !path.endsWith('.DS_Store')) problems.push(`${path} is not in the lock file`)
}

for (const font of lock.fonts) {
  if (!(`public/fonts/${font.id}/OFL.txt` in outputs)) problems.push(`${font.family} is missing OFL.txt`)
}

const cssPath = join(webDir, 'src/styles/fonts.css')
const css = existsSync(cssPath) ? readFileSync(cssPath, 'utf8') : ''
for (const [, , url] of css.matchAll(/url\(\s*(['"]?)([^'")]+)\1\s*\)/g)) {
  if (/^[a-z]+:/i.test(url)) problems.push(`fonts.css references an external URL ${url}`)
  else if (!existsSync(resolve(join(webDir, 'src/styles'), url))) problems.push(`${url} referenced by fonts.css does not exist`)
}

if (problems.length > 0) {
  for (const problem of problems) console.error(`check-fonts: ${problem}`)
  process.exit(1)
}
console.log(`check-fonts: ${Object.keys(outputs).length} files match the lock file`)
